import {validRetargetAsset} from './animation-retarget-assets.js';
import {validAnimationSync} from './animation-sync.js';

// Uniform positive time scaling preserves interpolation: weighted handles are
// interval fractions, controls are Y offsets, and slopes are value/second.
export function* skeletalRetimeJob(data,options={}){
 if(!options||typeof options!=='object'||Array.isArray(options)||Object.keys(options).some(key=>key!=='duration'))throw Error('길이 조정 옵션을 확인하세요.');const{duration}=options;
 if(!validRetargetAsset('skeletalclip',data)||!Number.isFinite(duration)||duration<.000001||duration>86400)throw Error('골격 클립·새 길이 범위를 확인하세요.');
 if(data.sync!==undefined&&!validAnimationSync(data))throw Error('클립 동기화 메타데이터를 확인하세요.');
 for(const track of data.tracks){if(track.interpolation!==undefined&&![2300,2301,2302].includes(track.interpolation)||track.type==='quaternion'&&track.interpolation===2302)throw Error('클립 보간을 확인하세요.');let previous=-Infinity;for(const time of track.times){const stored=Math.fround(time);if(stored<=previous)throw Error('원래 키 시간이 Float32 해상도에서 겹쳐요.');previous=stored;}}
 const ratio=duration/data.duration,summary={changed:duration!==data.duration,previousDuration:data.duration,duration,timeScale:ratio,playbackRate:1/ratio,tracks:data.tracks.length,keys:data.tracks.reduce((n,t)=>n+t.times.length,0),curves:data.curves?.length||0};if(!summary.changed)return{data,summary};
 const time=value=>value===data.duration?duration:value*ratio;let processed=0;const next={...data,duration,tracks:[]};
 for(const track of data.tracks){const times=new Array(track.times.length);let previous=-Infinity;for(let i=0;i<times.length;i++){times[i]=time(track.times[i]);const stored=Math.fround(times[i]);if(!Number.isFinite(stored)||stored<=previous)throw Error('새 길이에서 키 시간이 Float32 해상도로 겹쳐요.');previous=stored;if(++processed%4096===0)yield;}next.tracks.push({...track,times});}
 for(const field of ['notifies','notifyStates'])if(data[field])next[field]=data[field].map(row=>({...row,time:time(row.time),...(field==='notifyStates'?{duration:row.duration*ratio}:{})}));
 if(data.sync)next.sync={...data.sync,markers:data.sync.markers.map(row=>({...row,time:time(row.time)}))};
 if(data.curves){next.curves=[];for(const curve of data.curves){const result={...curve,keys:[]};for(const key of curve.keys){const value={...key,time:time(key.time)};for(const field of ['arriveTangent','leaveTangent'])if(key[field]!==undefined)value[field]=key[field]/ratio;result.keys.push(value);if(++processed%4096===0)yield;}if(curve.infinityDomain){const domain=curve.infinityDomain;result.infinityDomain={start:time(domain.start),end:time(domain.end),ranges:domain.ranges.map(row=>({start:time(row.start),end:time(row.end)}))};}next.curves.push(result);}}
 if(!validRetargetAsset('skeletalclip',next)||next.sync&&!validAnimationSync(next))throw Error('길이 변경 후 시간·접선·알림의 표현 범위를 넘었어요.');return{data:next,summary};
}
export function retimeSkeletalClip(data,options){const job=skeletalRetimeJob(data,options);for(;;){const step=job.next();if(step.done){Object.assign(data,step.value.data);return step.value.summary;}}}
export async function prepareSkeletalRetime(data,options,pause=()=>new Promise(r=>setTimeout(r,0))){const job=skeletalRetimeJob(data,options);try{for(;;){const step=job.next();if(step.done)return step.value;await pause();}}finally{job.return();}}
export const skeletalRetimeContract={command:'skeletal.retime',options:'path, expectedRevision, duration seconds (1e-6..86400), dryRun?:bool, includeData?:bool',scope:'Uniform positive time scale of existing v1 TRS/indexed/morph tracks, notifies/states, optional sync markers, numeric curves and explicit infinity domains. Original names/IDs/payload/extension fields remain.',fidelity:'No sampling or key/value reduction. Interpolation mode, values, horizontal fractional weights and explicit Y controls retained; explicit slopes divided by timeScale. Float32 track collisions/unsupported interpolation and output bounds reject atomically.',publication:'4096-key cooperative preparation, original source retained until complete; human one Undo and AI final document revision/identity/path/play-state check. Default compact preview; includeData returns detached proposed data.',cost:'Changed time arrays and curve key records; unchanged value arrays shared only inside pure plan. Ordinary whole document validation/Undo still apply.',limits:['Reverse/nonuniform time warp or value curve editing','Model-contained clips need extraction first','GUI/native binary/GPU/device verification is separate']};
